[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$ContractPath,[Parameter(Mandatory=$true)][string]$FixturePath,[ValidateSet('GET','HEAD')][string]$Method='GET',[string]$ReceiptPath='')
$ErrorActionPreference='Stop';$root=[IO.Path]::GetFullPath((Get-Location).Path).TrimEnd('\')+'\';$contract=(Resolve-Path $ContractPath).Path;$fixture=(Resolve-Path $FixturePath).Path;if(-not $contract.StartsWith($root,[StringComparison]::OrdinalIgnoreCase)-or -not $fixture.StartsWith($root,[StringComparison]::OrdinalIgnoreCase)){throw 'Contract and fixture must remain under project root.'};$c=Get-Content $contract -Raw -Encoding UTF8|ConvertFrom-Json;$body=Get-Content $fixture -Raw -Encoding UTF8;if($c.mode -ne 'local-adapter' -or $c.network.enabled){throw 'Local adapter requires mode=local-adapter with network disabled.'};if(@($c.operationPolicy.allowedMethods)-notcontains $Method){throw 'Method is not allowlisted.'};$hash=(Get-FileHash $fixture -Algorithm SHA256).Hash.ToLowerInvariant();$record=[ordered]@{schemaVersion=1;recordType='WebPageStudioBackendRuntimeReceipt';receiptId=('local-adapter-'+[guid]::NewGuid().ToString('N'));contractId=$c.contractId;status='passed';method=$Method;targetHost='local-fixture';allowlist=[ordered]@{decision='not-evaluated';matchedHost='local-fixture'};timeoutSeconds=[int]$c.network.timeoutSeconds;retry=[ordered]@{maxAttempts=[int]$c.retry.maxAttempts;retryable=[bool]$c.retry.enabled;exhausted=$false};recovery=[ordered]@{action='none';outcome='not-needed'};attempts=1;networkCalls=0;httpStatus=200;error='';cancellation=[ordered]@{requested=$false;observed=$false};redaction=[ordered]@{applied=$true;responseBodyPersisted=$false;sensitiveHeadersPersisted=$false};fixtureHash=$hash;fixtureBytes=([Text.Encoding]::UTF8.GetByteCount($body));runtimeStatus='runtime-passed';nonClaims=@('Local fixture adapter does not prove network reachability, TLS, CDN or production service health.','Fixture body is hashed and not copied into the receipt.')};if([string]::IsNullOrWhiteSpace($ReceiptPath)){$ReceiptPath='ES/Output/WebPageStudio/local-adapter-runtime-receipt.json'};$out=Join-Path $root $ReceiptPath;New-Item -ItemType Directory (Split-Path $out) -Force|Out-Null;[IO.File]::WriteAllText($out,($record|ConvertTo-Json -Depth 10),[Text.UTF8Encoding]::new($false));$record|ConvertTo-Json -Depth 10
